// AI pre-translation of My QR Code html keys carrying TAG that are still empty in a language.
// Built 22 Oct 2026 for MYQRCODE-10898 (minimum QR code size guide, 138 keys x 29 languages written 22 Oct), adapted from the Realchecker FE pipeline.
// HTML-file project: writes go one by one through PUT /translations/{id} (PUT /keys rejects translations here).
// Keep MODE 'check'; switch to 'write' deliberately for a run, then back. Instance timeout is 40 min. TEST_ONE writes a single translation.
const MODE = 'check';
const TEST_ONE = false;
const LANGS = ['cs', 'da', 'de', 'el', 'es', 'et', 'fi', 'fil', 'fr', 'hr', 'hu', 'id', 'it', 'ko', 'lt', 'lv', 'ms', 'nl', 'no', 'pl', 'pt', 'ro', 'sk', 'sl', 'sv', 'th', 'tr', 'uk', 'vi'];
const TAG = 'MYQRCODE-10898';
const CHUNK = 35;
const PROJECT = '18564477693fc9bba4cec8.54789459';
const BATCH = "This batch: a long-form SEO guide article moved from the WordPress blog to a localized page on myqrcode.com. EDIT for the next article.";
const NOTES = "BATCH NOTES: write as a native editorial article; consistent terminology; numbers in local convention; brand \"My QR Code\" never translated (\"MyQRCode\" -> \"My QR Code\"); headings in local capitalization; one space after </strong>; do not correct facts; use the language's typographic quotation marks.";
const ANCHORS = [];
const DESCS = {};
return [{ json: { mode: MODE, test_one: TEST_ONE, langs: LANGS, tag: TAG, chunk: CHUNK, project: PROJECT, batch: BATCH, notes: NOTES, anchors: ANCHORS, descs: DESCS } }];

const cfg = $('Config').first().json;
const NAME = { cs: /czech/i, da: /danish/i, de: /german/i, el: /greek/i, es: /spanish/i, et: /estonian/i, fi: /finnish/i, fil: /filipino|tagalog/i, fr: /french/i, hr: /croatian/i, hu: /hungarian/i, id: /indonesian/i, it: /italian/i, ko: /korean/i, lt: /lithuanian/i, lv: /latvian/i, ms: /malay/i, nl: /dutch/i, no: /norwegian/i, pl: /polish/i, pt: /portuguese/i, ro: /romanian/i, sk: /slovak/i, sl: /sloven/i, sv: /swedish/i, th: /thai/i, tr: /turkish/i, uk: /ukr/i, vi: /vietnamese/i };
const files = (($input.first().json || {}).files) || [];
const out = [];
for (const iso of cfg.langs) {
  const rx = NAME[iso];
  // Google Docs export as text. Best 3 candidates per language (style-guide-named, newest), emitted worst-first:
  // Build jobs keeps the LAST export that succeeds, i.e. the best guide the credential can read.
  const cand = files.filter(function (f) { return rx && rx.test(String(f.name || '')) && f.mimeType === 'application/vnd.google-apps.document'; })
    .sort(function (a, b) { const sa = /style guide/i.test(a.name) ? 1 : 0, sb = /style guide/i.test(b.name) ? 1 : 0; return sb - sa || String(b.modifiedTime).localeCompare(String(a.modifiedTime)); });
  for (const c of cand.slice(0, 3).reverse()) { out.push({ json: { iso: iso, name: c.name, url: 'https://www.googleapis.com/drive/v3/files/' + c.id + '/export?mimeType=text%2Fplain' } }); }
}
if (!out.length) { out.push({ json: { iso: '__none__', name: '', url: 'https://www.googleapis.com/drive/v3/about?fields=user' } }); }
return out;

// TM corpus: the My QR Code family (My QR Code, My QR Code html, QRcreate, WAPP), legal projects excluded.
const b = $input.first().json.body || $input.first().json;
if (!Array.isArray(b.projects)) { throw new Error('projects fetch failed'); }
const re = /(my ?qr ?code|qr ?create|wapp)/i;
return b.projects.filter(function (p) { return re.test(p.name) && !/legal/i.test(p.name); })
  .map(function (p) { return { json: { pid: p.project_id, name: p.name, url: 'https://api.lokalise.com/api2/projects/' + p.project_id + '/keys?include_translations=1&disable_references=1&filter_archived=exclude&limit=500&pagination=cursor' } }; });

// Builds one OpenAI request per (language, chunk of keys). Read-only. Targets: keys in cfg.project carrying cfg.tag.
const cfg = $('Config').first().json;
const FE = cfg.project;
const LN = { cs: 'Czech', da: 'Danish', de: 'German', el: 'Greek', es: 'Spanish (Spain)', et: 'Estonian', fi: 'Finnish', fil: 'Filipino', fr: 'French', hr: 'Croatian', hu: 'Hungarian', id: 'Indonesian', it: 'Italian', ko: 'Korean', lt: 'Lithuanian', lv: 'Latvian', ms: 'Malay', nl: 'Dutch', no: 'Norwegian (Bokmål)', pl: 'Polish', pt: 'Brazilian Portuguese (pt-BR)', ro: 'Romanian', sk: 'Slovak', sl: 'Slovenian', sv: 'Swedish', th: 'Thai', tr: 'Turkish', uk: 'Ukrainian', vi: 'Vietnamese' };
const ISO_BY_ID = { 765: 'cs', 767: 'da', 666: 'de', 761: 'el', 640: 'en', 1056: 'es', 673: 'fr', 793: 'hr', 757: 'id', 734: 'it', 733: 'ko', 749: 'ms', 737: 'nl', 760: 'no', 759: 'no', 748: 'pl', 708: 'pt', 770: 'ro', 799: 'sk', 754: 'sv', 753: 'th', 744: 'tr', 769: 'uk', 774: 'vi' };
function txt(v) { if (v === null || v === undefined || typeof v === 'object') { return ''; } return String(v); }
function kn(k) { const n = k.key_name || {}; return typeof n === 'string' ? n : (n.web || n.other || ''); }
const corpus = []; const targets = [];
for (const it of $('Fetch corpus').all()) {
  const b = it.json.body || {}; if (!Array.isArray(b.keys)) { continue; }
  for (const k of b.keys) {
    if (k.is_archived) { continue; }
    const tr = {}; let en = '';
    for (const t of (k.translations || [])) { const s = txt(t.translation); if (t.language_iso === 'en') { en = s; } else if (s.trim()) { tr[t.language_iso] = s; } }
    if (!en.trim()) { continue; }
    const row = { id: k.key_id, name: kn(k), pid: b.project_id, en: en, t: tr, d: String(cfg.descs[String(k.key_id)] || k.description || '') };
    if (b.project_id === FE && (k.tags || []).indexOf(cfg.tag) !== -1) { targets.push(row); } else { corpus.push(row); }
  }
}
if (!targets.length) { throw new Error('No target keys found for tag ' + cfg.tag); }
targets.sort(function (a, b) { return a.id - b.id; });
function norm(s) { return String(s).replace(/<[^>]+>/g, ' ').replace(/\[%[^\]]*\]/g, ' X ').replace(/[’‘]/g, "'").replace(/\s+/g, ' ').trim().toLowerCase(); }
function toks(s) { return new Set((norm(s).match(/[\p{L}\p{N}']{2,}/gu) || [])); }
for (const c of corpus) { c.n = norm(c.en); c.w = toks(c.en); }
const byN = {}; for (const c of corpus) { (byN[c.n] = byN[c.n] || []).push(c); }
for (const t of targets) {
  t.n = norm(t.en); const W = toks(t.en); const ex = byN[t.n] || [];
  const fz = [];
  if (W.size >= 2 && W.size <= 40) {
    for (const c of corpus) {
      if (c.n === t.n || !c.w.size) { continue; }
      const r = c.w.size / W.size; if (r < 0.5 || r > 2) { continue; }
      let i = 0; W.forEach(function (x) { if (c.w.has(x)) { i++; } });
      const sc = 2 * i / (W.size + c.w.size);
      if (sc >= 0.6) { fz.push({ c: c, sc: sc }); }
    }
  }
  fz.sort(function (a, b) { return b.sc - a.sc; });
  t.ex = ex.slice(0, 3);
  t.fz = fz.slice(0, 3);
}
// Terminology anchors: short existing My QR Code strings containing the article's key terms.
const TERMS = ['quiet zone', 'error correction', 'micro qr', 'frame qr', 'dynamic qr', 'static qr', 'scan', 'module', 'qr code generator', 'customiz', 'business card', 'menu'];
const termRows = corpus.filter(function (c) { if (c.en.length > 80) { return false; } const l = c.en.toLowerCase(); return TERMS.some(function (x) { return l.indexOf(x) !== -1; }); });
const RULES = {}, JUDGE = {};
for (const it of $('Style rules').all()) { const r = it.json || {}; if (!r.iso || r.iso === '*') { continue; } let l = []; try { l = JSON.parse(r.rules_json || '[]'); } catch (e) { } RULES[r.iso] = l.filter(function (x) { return !x.project || x.project !== 'personality'; }).map(function (x) { return (x.desc || x.id) + (x.suggest ? ' (use: ' + x.suggest + ')' : ''); }); JUDGE[r.iso] = r.judgement || ''; }
const FB = {};
for (const it of $('Feedback').all()) { const r = it.json || {}; if (!r.iso || !r.decision) { continue; } (FB[r.iso] = FB[r.iso] || []).push({ d: r.decision, rule: String(r.rule || '').slice(0, 80), en: String(r.en || '').slice(0, 120), t: String(r.translation || '').slice(0, 120), why: String(r.reason || r.issue || '').slice(0, 160) }); }
const GUIDE = {};
const gp = $('Guide plan').all(); const ge = $('Export guides').all();
for (let i = 0; i < gp.length; i++) { const iso = gp[i].json.iso; const g = ge[i] ? ge[i].json : {}; const s = typeof g.data === 'string' ? g.data : ''; if (s && iso !== '__none__' && !/^\s*[{<]/.test(s)) { GUIDE[iso] = s.replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').slice(0, 24000); } }
let terms = [];
for (const it of $('Glossary').all()) { const b = it.json.body !== undefined ? it.json.body : it.json; terms = terms.concat((b && (b.data || b.glossary_terms || b.terms)) || []); }
function yes(v) { return v === true || v === 1 || String(v).toLowerCase() === 'yes' || String(v).toLowerCase() === 'true'; }
function tagList(t) { const raw = t.tags || []; const arr = Array.isArray(raw) ? raw : String(raw).split(','); return arr.map(function (x) { return String(typeof x === 'object' && x ? (x.name || x.tag || '') : x).trim().toLowerCase(); }).filter(function (x) { return x; }); }
const inScope = terms.filter(function (t) { const tg = tagList(t); return !tg.length || tg.some(function (x) { return x === 'shared' || /qr/.test(x); }); });
function esc(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function glossFor(iso, ens) {
  const out = []; const blob = ens.join(' \n ');
  for (const t of inScope) {
    const src = String(t.term || '').trim(); if (!src) { continue; }
    const rx = new RegExp('(?<![\\p{L}\\p{N}])' + esc(src) + '(?![\\p{L}\\p{N}])', 'u' + (yes(t.caseSensitive) ? '' : 'i'));
    if (!rx.test(blob)) { continue; }
    let tgt = '', note = '';
    for (const tr of (t.translations || [])) { const i2 = ISO_BY_ID[tr.langId || tr.lang_id] || (String(tr.langIso || tr.lang_iso || '') === 'pt_BR' ? 'pt' : String(tr.langIso || tr.lang_iso || '')); if (i2 === iso) { tgt = String(tr.translation || '').trim(); note = String(tr.description || '').trim(); } }
    const translatable = t.translatable === undefined ? true : yes(t.translatable);
    if (translatable && !tgt && !yes(t.forbidden)) { continue; }
    out.push({ term: src, target: translatable ? tgt : '(do not translate: keep as is)', forbidden: yes(t.forbidden) || undefined, note: (note || String(t.description || '')).slice(0, 160) || undefined });
  }
  return out;
}
const NL = String.fromCharCode(10);
const jobs = [];
for (const iso of cfg.langs) {
  const todo = targets.filter(function (t) { return !t.t[iso]; });
  if (!todo.length) { continue; }
  const seen = {}; const anchors = [];
  for (const a of termRows) { if (!a.t[iso] || seen[a.n]) { continue; } seen[a.n] = 1; anchors.push({ en: a.en, t: a.t[iso] }); if (anchors.length >= 60) { break; } }
  const fb = (FB[iso] || []).slice(-15);
  for (let c = 0; c < todo.length; c += cfg.chunk) {
    const part = todo.slice(c, c + cfg.chunk);
    const prev = c > 0 ? todo.slice(Math.max(0, c - 3), c).map(function (t) { return t.en; }) : [];
    const items = part.map(function (t) {
      const tm = [];
      for (const e of t.ex) { if (e.t[iso]) { tm.push({ match: '100% (exact)', en: e.en, translation: e.t[iso] }); } }
      for (const f of t.fz) { if (f.c.t[iso]) { tm.push({ match: 'fuzzy ' + Math.round(f.sc * 100) + '%', en: f.c.en, translation: f.c.t[iso] }); } }
      return { id: String(t.id), element: t.name, en: t.en, context: t.d.slice(0, 600), tm: tm.length ? tm.slice(0, 3) : undefined };
    });
    const SYS = [
      'You are a senior native ' + LN[iso] + ' localizer and editor for My QR Code (myqrcode.com), a web app for creating, customizing and tracking QR codes. ' + cfg.batch,
      'Translate every item from English into ' + LN[iso] + '. Write natural, idiomatic, publication-quality article copy a native reader would expect from a professional website, not a literal rendering. Items are consecutive parts of one article: keep terminology, register and style consistent across all of them.',
      'PRIORITIES, in order: (1) the ' + LN[iso] + ' STYLE GUIDE below (register/formality, tone, typography, number/date/punctuation conventions); (2) the GLOSSARY (use the approved target terms; never use forbidden terms; keep brand names unchanged); (3) TRANSLATION MEMORY: reuse 100% matches unless they break the glossary or style guide; reuse terminology from fuzzy matches; (4) ANCHORS: existing My QR Code UI translations: use the same wording for the same concepts (e.g. how QR code, scan, customize, error correction are rendered in the product).',
      cfg.notes,
      'MECHANICS (strict): keep every HTML tag exactly as in the source, character for character, including attributes: <a href="...">...</a> keeps the same href value unchanged (never translate or change URLs); <strong>...</strong> keeps the same count; translate the text inside the tags. Line breaks in the source separate sentences: you may keep them between sentences. Do not add leading or trailing spaces.',
      'Translate everything: do not leave English words untranslated unless they are brand or product names, standards (ISO/IEC 18004), file formats (PDF, SVG), acronyms (SKU, PCB, rMQR, SQRC) or the glossary says to keep them.',
      'Return ONLY JSON: {"t":{"<id>":"<translation>", ...}} keyed by the numeric item id, with an entry for EVERY id.',
      '',
      '=== ' + LN[iso] + ' STYLE GUIDE (source of truth) ===',
      GUIDE[iso] ? GUIDE[iso] : '(full guide unavailable; use the rules below)',
      '',
      '=== Style rules distilled by the i18n team ===',
      (RULES[iso] || []).slice(0, 40).join(NL) || '(none)',
      JUDGE[iso] ? ('Judgement notes: ' + JUDGE[iso]) : '',
      fb.length ? ('Reviewer precedent (i18n lead decisions on earlier audits, follow them): ' + JSON.stringify(fb)) : ''
    ].join(NL);
    const user = { language: LN[iso], glossary: glossFor(iso, part.map(function (t) { return t.en; })), anchors: anchors, preceding_text_for_context: prev.length ? prev : undefined, items: items };
    jobs.push({ json: { iso: iso, chunk: c / cfg.chunk, ids: part.map(function (t) { return t.id; }), guide: !!GUIDE[iso], body: JSON.stringify({ model: 'gpt-4.1', temperature: 0.2, max_tokens: 20000, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: SYS }, { role: 'user', content: JSON.stringify(user) }] }) } });
  }
}
return jobs;

// Parses OpenAI answers, validates mechanics, unifies identical English. Read-only.
const jobs = $('Build jobs').all().map(function (i) { return i.json; });
const res = $input.all().map(function (i) { return i.json || {}; });
function bag(s, rx) { const m = {}; for (const x of (String(s).match(rx) || [])) { m[x] = (m[x] || 0) + 1; } return JSON.stringify(Object.keys(m).sort().map(function (k) { return k + ':' + m[k]; })); }
const TAG = /<\/?[A-Za-z]+(?:\s[^>]*)?>/g;
function fix(t) { return String(t).replace(/<\/strong>(?=[^\s<.,:;!?)])/g, '</strong> ').replace(/MyQRCode/g, 'My QR Code'); }
function check(en, t) {
  if (!t || !String(t).trim()) { return 'empty'; }
  if (bag(en, TAG) !== bag(t, TAG)) { return 'tag or link mismatch'; }
  if (String(t).trim() === String(en).trim() && en.split(/\s+/).length >= 4) { return 'untranslated'; }
  if (t !== t.trim() && en === en.trim()) { return 'extra whitespace'; }
  const ne = (String(en).match(/\d/g) || []).length, nt = (String(t).match(/\d/g) || []).length;
  if (ne && Math.abs(ne - nt) > Math.max(2, ne * 0.25)) { return 'digits changed (' + ne + ' vs ' + nt + ')'; }
  return '';
}
const per = {}; const bad = []; const callErr = [];
for (let i = 0; i < jobs.length; i++) {
  const j = jobs[i]; const r = res[i] || {};
  const items = JSON.parse(JSON.parse(j.body).messages[1].content).items;
  let parsed = null;
  try { parsed = JSON.parse(String(r.choices[0].message.content).replace(/^```json|```$/g, '').trim()).t; } catch (e) { callErr.push({ iso: j.iso, chunk: j.chunk, err: r.error ? JSON.stringify(r.error).slice(0, 200) : String(e.message || e) }); continue; }
  per[j.iso] = per[j.iso] || {};
  for (const it of items) {
    let t = parsed ? parsed[it.id] : undefined;
    if (typeof t !== 'string') { bad.push({ iso: j.iso, key: it.element, why: 'missing in answer' }); continue; }
    t = fix(t);
    const why = check(it.en, t);
    if (why) { bad.push({ iso: j.iso, id: it.id, key: it.element, why: why, en: it.en.slice(0, 200), t: String(t).slice(0, 300) }); continue; }
    per[j.iso][it.id] = { key: it.element, en: it.en, t: t, tm: it.tm ? it.tm[0].match : '' };
  }
}
let unified = 0;
for (const iso in per) {
  const groups = {};
  for (const id in per[iso]) { const e = per[iso][id].en.trim(); (groups[e] = groups[e] || []).push(id); }
  for (const e in groups) {
    const ids = groups[e]; if (ids.length < 2) { continue; }
    const best = per[iso][ids[0]].t;
    for (const id of ids) { if (per[iso][id].t !== best) { per[iso][id].t = best; unified++; } }
  }
}
const ids = []; for (const j of jobs) { for (const x of j.ids) { if (ids.indexOf(x) === -1) { ids.push(x); } } }
const stats = {}; for (const iso in per) { const v = Object.values(per[iso]); stats[iso] = { ok: v.length, tm_exact_reused: v.filter(function (x) { return x.tm.indexOf('100%') === 0; }).length }; }
return [{ json: { per: per, bad: bad, call_errors: callErr, unified: unified, stats: stats, ids: ids.join(','), guides: jobs.reduce(function (a, j) { a[j.iso] = j.guide; return a; }, {}) } }];

// Guard: writes only into translations that are still empty right now, only if EN is unchanged.
// HTML-file projects reject translations via PUT /keys, so each translation is written with PUT /translations/{translation_id}, unverified.
const p = $('Parse and validate').first().json; const cfg = $('Config').first().json;
const b = $('Guard fetch').first().json.body || {};
if (!Array.isArray(b.keys)) { throw new Error('Guard fetch failed: ' + JSON.stringify(b).slice(0, 200)); }
const live = {};
for (const k of b.keys) { const m = {}; const tid = {}; for (const t of (k.translations || [])) { m[t.language_iso] = typeof t.translation === 'string' ? t.translation : JSON.stringify(t.translation); tid[t.language_iso] = t.translation_id; } live[k.key_id] = { m: m, tid: tid, arch: k.is_archived }; }
const out = []; const summary = {};
for (const iso in p.per) {
  let n = 0, skipped = 0, enChanged = 0, noId = 0;
  for (const id in p.per[iso]) {
    const L = live[id]; if (!L || L.arch) { skipped++; continue; }
    if (String(L.m.en || '') !== p.per[iso][id].en) { enChanged++; continue; }
    if (String(L.m[iso] || '').trim()) { skipped++; continue; }
    if (!L.tid[iso]) { noId++; continue; }
    out.push({ iso: iso, key_id: Number(id), tid: L.tid[iso], body: JSON.stringify({ translation: p.per[iso][id].t, is_unverified: true }) });
    n++;
  }
  summary[iso] = { to_write: n, skipped_now_filled: skipped, en_changed: enChanged, no_translation_id: noId };
}
const sample = {}; for (const iso in p.per) { sample[iso] = Object.values(p.per[iso]); }
return [{ json: { mode: cfg.mode, test_one: !!cfg.test_one, summary: summary, stats: p.stats, invalid: p.bad, call_errors: p.call_errors, unified: p.unified, guides: p.guides, translations: sample, writes: out } }];

// Write gate: nothing is written in MODE 'check'; test_one writes only the first translation.
const d = $input.first().json;
if (d.mode !== 'write') { return []; }
const w = d.test_one ? d.writes.slice(0, 1) : d.writes;
return w.map(function (x) { return { json: x }; });

const g = $('Gate').all().map(function (i) { return i.json; });
const per = {}; const fails = [];
$input.all().forEach(function (r, i) {
  const x = g[i] || {}; const b = r.json.body || {}; const ok = r.json.statusCode === 200 && b.translation && typeof b.translation.translation === 'string';
  per[x.iso] = per[x.iso] || { ok: 0, failed: 0 };
  if (ok) { per[x.iso].ok++; } else { per[x.iso].failed++; fails.push({ iso: x.iso, key_id: x.key_id, status: r.json.statusCode, error: JSON.stringify(b.error || b).slice(0, 200) }); }
});
return [{ json: { per_language: per, failures: fails.slice(0, 50), failed_total: fails.length, sample: $input.all().slice(0, 1).map(function (r) { return r.json.body; }) } }];
